mapper.delete:
delete from pv_telemetry
where collect_time < #{cutoffTime}
order by collect_time asc, telemetry_id asc
limit #{limit}

mapper.select:
select s.station_id, s.station_name, ifnull(t.tag_name, '未分组') as tag_name, x.hour_of_day, cast(sum(x.delta) as decimal(12,2)) as yield_kwh from ( select y.station_id, y.inverter_id, y.collect_date, y.hour_of_day, greatest( max(case when y.rn_desc = 1 then y.daily_yield end) - max(case when y.rn_asc = 1 then y.daily_yield end), 0 ) as delta from ( select g.station_id, pt.inverter_id, date(pt.collect_time) as collect_date, hour(pt.collect_time) as hour_of_day, pt.daily_yield, row_number() over ( partition by g.station_id, pt.inverter_id, date(pt.collect_time), hour(pt.collect_time) order by pt.collect_time asc, pt.telemetry_id asc ) as rn_asc, row_number() over ( partition by g.station_id, pt.inverter_id, date(pt.collect_time), hour(pt.collect_time) order by pt.collect_time desc, pt.telemetry_id desc ) as rn_desc from pv_telemetry pt inner join pv_inverter i on i.inverter_id = pt.inverter_id inner join pv_gateway g on g.gateway_id = i.gateway_id where pt.collect_time >= #{startTime} and pt.collect_time < date_add(#{endTime}, interval 1 second) ) y group by y.station_id, y.inverter_id, y.collect_date, y.hour_of_day ) x inner join pv_station s on s.station_id = x.station_id left join pv_station_tag t on t.tag_id = s.tag_id
and s.tag_id = #{tagId}
group by s.station_id, s.station_name, t.tag_name, x.hour_of_day order by s.station_id asc, x.hour_of_day asc

